-- ============================================
--  MIGRASI SETTINGS ke Supabase
--  Jalankan seluruh isi file ini di SQL Editor
-- ============================================

create table if not exists settings (
  key   text primary key,
  value text
);

alter table settings enable row level security;

create policy "settings boleh dibaca publik"
  on settings for select to anon using (true);

create policy "admin boleh tulis settings"
  on settings for insert to authenticated with check (true);
create policy "admin boleh update settings"
  on settings for update to authenticated using (true) with check (true);
create policy "admin boleh hapus settings"
  on settings for delete to authenticated using (true);

grant select on public.settings to anon, authenticated;
grant insert, update, delete on public.settings to authenticated;

-- ---- data existing ----
on conflict (key) do update set value = excluded.value;
